```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int val;
    int idx;
} Element;

int cmp_desc(const void *a, const void *b) {
    const Element *ea = (const Element *)a;
    const Element *eb = (const Element *)b;
    if (eb->val != ea->val) {
        return (eb->val > ea->val) - (eb->val < ea->val);
    }
    return ea->idx - eb->idx;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int *raw = (int *)malloc((n + 2) * sizeof(int));
    for (int i = 0; i < n; i++) {
        scanf("%d", &raw[i]);
    }

    // Comprime elementos adjacentes iguais e adiciona bordas de altura 0
    int *a = (int *)malloc((n + 2) * sizeof(int));
    int m = 0;
    a[m++] = 0; // borda esquerda

    for (int i = 0; i < n; i++) {
        if (m == 1 || raw[i] != a[m - 1]) {
            a[m++] = raw[i];
        }
    }
    a[m] = 0; // borda direita
    free(raw);

    // Cria lista de elementos a serem processados
    // Elementos válidos estão nos índices 1 até m - 1
    int num_elements = m - 1;
    Element *elems = (Element *)malloc(num_elements * sizeof(Element));
    for (int i = 1; i < m; i++) {
        elems[i - 1].val = a[i];
        elems[i - 1].idx = i;
    }

    // Ordena elementos por altura em ordem decrescente
    qsort(elems, num_elements, sizeof(Element), cmp_desc);

    int current_components = 0;
    int max_components = 0;

    int i = 0;
    while (i < num_elements) {
        int j = i;
        // Agrupa todos os elementos com a mesma altura
        while (j < num_elements && elems[j].val == elems[i].val) {
            int idx = elems[j].idx;
            int v = elems[j].val;
            int left_active = (a[idx - 1] > v);
            int right_active = (a[idx + 1] > v);

            if (!left_active && !right_active) {
                current_components++;
            } else if (left_active && right_active) {
                current_components--;
            }
            j++;
        }

        if (current_components > max_components) {
            max_components = current_components;
        }

        i = j;
    }

    // O corte divide o papel em 'max_components' pedaços superiores + 1 pedaço inferior
    printf("%d\n", max_components + 1);

    free(a);
    free(elems);
    return 0;
}
```

